Array.prototype.myMap = function (callback, thisArg) {
  if (typeof callback !== 'function') throw new TypeError(callback + ' is not a function');
  const result = new Array(this.length);
  for (let i = 0; i < this.length; i++) {
    if (i in this) result[i] = callback.call(thisArg, this[i], i, this);
  }
  return result;
};
console.log([1, 2, 3].myMap((n, i) => n * i)); // [0, 2, 6]

function myAll(items) {
  return new Promise((resolve, reject) => {
    const results = new Array(items.length);
    let done = 0;
    if (items.length === 0) return resolve(results);
    items.forEach((item, i) => {
      Promise.resolve(item).then((value) => {
        results[i] = value;
        if (++done === items.length) resolve(results);
      }, reject);
    });
  });
}
myAll([new Promise((r) => setTimeout(() => r('slow'), 50)), 'fast']).then(console.log); // ['slow', 'fast']

Function.prototype.myBind = function (context, ...preset) {
  const original = this;
  function bound(...later) {
    const self = this instanceof bound ? this : context;  // support new
    return original.apply(self, [...preset, ...later]);
  }
  bound.prototype = Object.create(original.prototype);
  return bound;
};
