function memoize(fn, max = 100) {
  const cache = new Map();
  return (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      const v = cache.get(key);
      cache.delete(key); cache.set(key, v);   // mark as recently used
      return v;
    }
    const v = fn(...args);
    cache.set(key, v);
    if (cache.size > max) cache.delete(cache.keys().next().value);
    return v;
  };
}

class Emitter {
  #events = new Map();
  on(name, fn) { (this.#events.get(name) ?? this.#events.set(name, []).get(name)).push(fn); return this; }
  off(name, fn) { this.#events.set(name, (this.#events.get(name) ?? []).filter((f) => f !== fn)); return this; }
  once(name, fn) { const w = (...a) => { this.off(name, w); fn(...a); }; return this.on(name, w); }
  emit(name, ...args) { [...(this.#events.get(name) ?? [])].forEach((fn) => fn(...args)); return this; }
}
const e = new Emitter();
