e.emit('hi', 1).emit('hi', 2); // once 1, always 1, always 2

function deleteNode(node) {
  if (!node || !node.next) throw new Error('Cannot delete the last node this way');
  node.value = node.next.value;
  node.next = node.next.next;
}

function mergeSort(arr) {
  if (arr.length <= 1) return arr;
  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));
  return merge(left, right);
}
function merge(a, b) {
  const out = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    out.push(a[i] <= b[j] ? a[i++] : b[j++]); // <= keeps it stable
  }
  return out.concat(a.slice(i), b.slice(j));
}
console.log(mergeSort([5, 2, 9, 1, 5])); // [1, 2, 5, 5, 9]

function insert(head, x) {
  const node = { value: x, next: null };
  if (!head) { node.next = node; return node; }
  let prev = head, next = head.next;
  do {
    const inGap = prev.value <= x && x <= next.value;
    const atTurn = prev.value > next.value && (x >= prev.value || x <= next.value);
    if (inGap || atTurn) break;
    prev = next;
    next = next.next;
  } while (prev !== head);
  prev.next = node;
  node.next = next;
  return head;
}
